import re
from collections import namedtuple

MANDATORY_COLUMN_DESCRIPTIONS = ['hex', 'type']


class HexSourceDescription(object):
    def __init__(self, line_template, separator, column_descripions, sample_line, protocol):
        """

        :param line_template:
        :param separator:
        :param column_descripions:
        :param sample_line:
        :param protocol:
        """
        assert protocol in ['rrc', 'nr-rrc', 'dynamic'], 'Only rrc supported currently'
        self.protocol = protocol
        self.source_separator = separator
        self.source_column_descriptions = column_descripions
        self._check_mandatory_columns(self.source_column_descriptions)
        self._check_sample_line_with_source_template(sample_line, line_template)
        self._data_tuple = namedtuple('data', self.source_column_descriptions)
        self.source_template = re.compile(line_template + r"\s")  # add white sign at the end to detect end of line

    def get_data_record(self, list_of_values):
        """
        Packs data received in list to tuple to provide access by name.
        :param list_of_values:
        :return:
        """
        return self._data_tuple(*list_of_values)

    def _check_mandatory_columns(self, column_names):
        for mandatory in MANDATORY_COLUMN_DESCRIPTIONS:
            assert mandatory in column_names, "Mandatory param: {} not in column description: {}".format(mandatory, column_names)

    def _check_sample_line_with_source_template(self, sample_line, line_template):
        compiled_line = re.compile(line_template)
        assert compiled_line.match(sample_line), \
            'Sample line: {} can not be parsed with line template: {}'.format(sample_line, line_template)
        assert len(self.source_column_descriptions) == len(re.split(self.source_separator, sample_line)), \
            "Column number: {} does not match number of items: {} split by separator: {}".format(len(self.source_column_descriptions),
                                                                                                 re.split(self.source_separator, sample_line),
                                                                                                 str(self.source_separator))


class UesimHexSourceDescription(HexSourceDescription):
    def __init__(self, line_template, separator, column_descripions, sample_line, protocol):
        """

        :param line_template:
        :param separator:
        :param column_descripions:
        :param sample_line:
        :param protocol:
        """
        super(UesimHexSourceDescription, self).__init__(line_template, separator, column_descripions, sample_line, protocol)
        self._data_tuple = namedtuple('data', self.source_column_descriptions + ['uesim_type'])


class RRCHexSourceDescription(UesimHexSourceDescription):
    def __init__(self, line_template, separator, column_descripions, sample_line, protocol='rrc'):
        """

        :param line_template:
        :param separator:
        :param column_descripions:
        :param sample_line:
        :param protocol:
        """
        super(RRCHexSourceDescription, self).__init__(line_template, separator, column_descripions, sample_line, protocol)


class NRRRCHexSourceDescription(UesimHexSourceDescription):
    def __init__(self, line_template, separator, column_descripions, sample_line, protocol='dynamic'):
        """

        :param line_template:
        :param separator:
        :param column_descripions:
        :param sample_line:
        :param protocol:
        """
        super(NRRRCHexSourceDescription, self).__init__(line_template, separator, column_descripions, sample_line, protocol)
